<?php require_once __DIR__.'/../includes/auth.php';$pageTitle='Reports';$base='/shop-inventory-management';$today=$pdo->query("SELECT COALESCE(SUM(grand_total),0) FROM sales WHERE status='completed' AND DATE(created_at)=CURDATE()")->fetchColumn();$month=$pdo->query("SELECT COALESCE(SUM(grand_total),0) FROM sales WHERE status='completed' AND YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())")->fetchColumn();$revenue=$pdo->query("SELECT COALESCE(SUM(grand_total),0) FROM sales WHERE status='completed'")->fetchColumn();$daily=$pdo->query("SELECT DATE(created_at) day,COUNT(*) orders,COALESCE(SUM(grand_total),0) revenue FROM sales WHERE status='completed' AND created_at>=CURDATE()-INTERVAL 6 DAY GROUP BY DATE(created_at) ORDER BY day DESC")->fetchAll();$best=$pdo->query("SELECT p.name,p.sku,SUM(si.quantity) units,SUM(si.line_total) revenue FROM sale_items si JOIN products p ON p.id=si.product_id JOIN sales s ON s.id=si.sale_id WHERE s.status='completed' GROUP BY p.id ORDER BY units DESC LIMIT 10")->fetchAll();$low=$pdo->query('SELECT name,sku,quantity,minimum_stock FROM products WHERE quantity<=minimum_stock ORDER BY quantity ASC,name')->fetchAll();$out=$pdo->query('SELECT name,sku,quantity,minimum_stock FROM products WHERE quantity=0 ORDER BY name')->fetchAll();require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1>Reports & insights</h1><p>Live sales and inventory summaries from your database.</p></div><button class="btn" onclick="window.print()">Print report</button></div><div class="stats-grid report-stats"><div class="stat-card"><div class="stat-icon blue">₹</div><div><span>Today's sales</span><strong><?=money($today)?></strong><small>Current day</small></div></div><div class="stat-card"><div class="stat-icon purple">▥</div><div><span>This month</span><strong><?=money($month)?></strong><small>Current month</small></div></div><div class="stat-card"><div class="stat-icon green">₹</div><div><span>Total revenue</span><strong><?=money($revenue)?></strong><small>Completed sales</small></div></div><div class="stat-card"><div class="stat-icon orange">⚠</div><div><span>Low-stock items</span><strong><?=count($low)?></strong><small>Need attention</small></div></div></div><div class="report-grid"><div class="panel"><div class="panel-header"><div><h2>Daily sales</h2><p>Last 7 days with transactions</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Orders</th><th>Revenue</th></tr></thead><tbody><?php if(!$daily):?><tr><td colspan="3" class="empty">No sales in the last 7 days.</td></tr><?php else:foreach($daily as $r):?><tr><td><?=e($r['day'])?></td><td><?=$r['orders']?></td><td><?=money($r['revenue'])?></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="panel"><div class="panel-header"><div><h2>Best-selling products</h2><p>Ranked by units sold</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units</th><th>Revenue</th></tr></thead><tbody><?php if(!$best):?><tr><td colspan="3" class="empty">No sales data yet.</td></tr><?php else:foreach($best as $r):?><tr><td><strong><?=e($r['name'])?></strong><small class="subline"><?=e($r['sku'])?></small></td><td><?=$r['units']?></td><td><?=money($r['revenue'])?></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="panel"><div class="panel-header"><div><h2>Low-stock report</h2><p>Quantity at or below minimum stock</p></div><span class="badge warning"><?=count($low)?> items</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>On hand</th><th>Minimum</th></tr></thead><tbody><?php if(!$low):?><tr><td colspan="3" class="empty">No low-stock products.</td></tr><?php else:foreach($low as $r):?><tr><td><?=e($r['name'])?><small class="subline"><?=e($r['sku'])?></small></td><td><?=$r['quantity']?></td><td><?=$r['minimum_stock']?></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="panel"><div class="panel-header"><div><h2>Out-of-stock report</h2><p>Items with zero available units</p></div><span class="badge danger"><?=count($out)?> items</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Minimum</th></tr></thead><tbody><?php if(!$out):?><tr><td colspan="3" class="empty">No out-of-stock products.</td></tr><?php else:foreach($out as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['sku'])?></td><td><?=$r['minimum_stock']?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div><?php require __DIR__.'/../includes/footer.php';?>
